const halfResetArena = `-- name: HalfResetArena :execrows
UPDATE app.arena
SET season     = $1,
    rating     = GREATEST($2::int,
                 $3::int
                 + ((rating - $3::int) * $4::int) / 10000),
    peak       = GREATEST($2::int,
                 $3::int
                 + ((rating - $3::int) * $4::int) / 10000),
    wins = 0, losses = 0, streak = 0, milestones = 0
WHERE season < $1
`

type HalfResetArenaParams struct {
	Season      int32
	FloorRating int32
	StartRating int32
	ResetBp     int32
}

// The bulk half of the season roll. A row already rolled (lazily, by
// UpsertArena) has the new season and is skipped.
func (q *Queries) HalfResetArena(ctx context.Context, arg HalfResetArenaParams) (int64, error) {
	result, err := q.db.Exec(ctx, halfResetArena,
		arg.Season,
		arg.FloorRating,
		arg.StartRating,
		arg.ResetBp,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

