const throneRaceByTotal = `-- name: ThroneRaceByTotal :many
SELECT k.id AS kingdom_id, k.name, k.tag,
       k.reputation::bigint AS reputation,
       (SELECT count(*) FROM app.players m
        WHERE m.kingdom_id = k.id AND m.state = 'active')::int AS members,
       (SELECT m.id FROM app.players m
        WHERE m.kingdom_id = k.id AND m.kingdom_role = 'king' LIMIT 1) AS king_id
FROM app.kingdoms k
WHERE (SELECT count(*) FROM app.players m
       WHERE m.kingdom_id = k.id AND m.state = 'active') >= $1::int
ORDER BY k.reputation DESC, k.created_at, k.id
LIMIT $2
`

type ThroneRaceByTotalParams struct {
	MinMembers int32
	Lim        int32
}

type ThroneRaceByTotalRow struct {
	KingdomID  uuid.UUID
	Name       string
	Tag        string
	Reputation int64
	Members    int32
	KingID     uuid.UUID
}

// The same race on the cumulative measure (total), the alternative the balance
// can switch to.
func (q *Queries) ThroneRaceByTotal(ctx context.Context, arg ThroneRaceByTotalParams) ([]ThroneRaceByTotalRow, error) {
	rows, err := q.db.Query(ctx, throneRaceByTotal, arg.MinMembers, arg.Lim)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ThroneRaceByTotalRow{}
	for rows.Next() {
		var i ThroneRaceByTotalRow
		if err := rows.Scan(
			&i.KingdomID,
			&i.Name,
			&i.Tag,
			&i.Reputation,
			&i.Members,
			&i.KingID,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const throneRaceByWeekGain = `-- name: ThroneRaceByWeekGain :many
SELECT k.id AS kingdom_id, k.name, k.tag,
       coalesce(w.reputation, 0)::bigint AS reputation,
       (SELECT count(*) FROM app.players m
        WHERE m.kingdom_id = k.id AND m.state = 'active')::int AS members,
       (SELECT m.id FROM app.players m
        WHERE m.kingdom_id = k.id AND m.kingdom_role = 'king' LIMIT 1) AS king_id
FROM app.kingdoms k
LEFT JOIN app.kingdom_week w ON w.kingdom_id = k.id AND w.uweek = $1
WHERE (SELECT count(*) FROM app.players m
       WHERE m.kingdom_id = k.id AND m.state = 'active') >= $2::int
ORDER BY coalesce(w.reputation, 0) DESC, k.created_at, k.id
LIMIT $3
`

type ThroneRaceByWeekGainParams struct {
	Uweek      int64
	MinMembers int32
	Lim        int32
}

type ThroneRaceByWeekGainRow struct {
	KingdomID  uuid.UUID
	Name       string
	Tag        string
	Reputation int64
	Members    int32
	KingID     uuid.UUID
}

// The week's race, on the measure the Throne is decided by (week_gain).
// Kingdoms under min_members are not candidates and are not shown.
func (q *Queries) ThroneRaceByWeekGain(ctx context.Context, arg ThroneRaceByWeekGainParams) ([]ThroneRaceByWeekGainRow, error) {
	rows, err := q.db.Query(ctx, throneRaceByWeekGain, arg.Uweek, arg.MinMembers, arg.Lim)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ThroneRaceByWeekGainRow{}
	for rows.Next() {
		var i ThroneRaceByWeekGainRow
		if err := rows.Scan(
			&i.KingdomID,
			&i.Name,
			&i.Tag,
			&i.Reputation,
			&i.Members,
			&i.KingID,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const upsertArena = `-- name: UpsertArena :one
INSERT INTO app.arena (player_id, season, rating, peak)
VALUES ($1, $2, $3, $3)
ON CONFLICT (player_id) DO UPDATE
SET season     = EXCLUDED.season,
    rating     = CASE WHEN app.arena.season = EXCLUDED.season THEN app.arena.rating
                      ELSE GREATEST($4::int,
                           $3::int
                           + ((app.arena.rating - $3::int)
                              * $5::int) / 10000) END,
    peak       = CASE WHEN app.arena.season = EXCLUDED.season THEN app.arena.peak
                      ELSE GREATEST($4::int,
                           $3::int
                           + ((app.arena.rating - $3::int)
                              * $5::int) / 10000) END,
    wins       = CASE WHEN app.arena.season = EXCLUDED.season THEN app.arena.wins ELSE 0 END,
    losses     = CASE WHEN app.arena.season = EXCLUDED.season THEN app.arena.losses ELSE 0 END,
    streak     = CASE WHEN app.arena.season = EXCLUDED.season THEN app.arena.streak ELSE 0 END,
    milestones = CASE WHEN app.arena.season = EXCLUDED.season THEN app.arena.milestones ELSE 0 END
RETURNING player_id, season, rating, peak, wins, losses, streak, milestones, last_at
`

type UpsertArenaParams struct {
	PlayerID    uuid.UUID
	Season      int32
	StartRating int32
	FloorRating int32
	ResetBp     int32
}

// A lord's standing, made if it is missing and rolled if it is a season stale.
// The half reset happens HERE as well as in the job: whichever runs first, the
// other is a no-op, and a lord never fights a fresh season on last season's
// rating.
func (q *Queries) UpsertArena(ctx context.Context, arg UpsertArenaParams) (AppArena, error) {
	row := q.db.QueryRow(ctx, upsertArena,
		arg.PlayerID,
		arg.Season,
		arg.StartRating,
		arg.FloorRating,
		arg.ResetBp,
	)
	var i AppArena
	err := row.Scan(
		&i.PlayerID,
		&i.Season,
		&i.Rating,
		&i.Peak,
		&i.Wins,
		&i.Losses,
		&i.Streak,
		&i.Milestones,
		&i.LastAt,
	)
	return i, err
}
